import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`freelance-work`,heroTitle:`Your digital team, ready now`,heroSubtitle:`Perplexity Computer takes your brief, does the work, and delivers finished results — automatically.`,inputUrlCta:`Start my project`,inputUrlPlaceholder:`your project brief`,inputUrlPrefill:`Take this project brief: {url}. Turn it into finished freelance work. 1) Extract the goal, audience, deliverables, brand constraints, source material, quality bar, and open questions. 2) Break the project into research, strategy, drafting, analysis, review, and final packaging tasks. 3) Produce the requested deliverables with supporting notes, assumptions, and clear revision points. 4) Organize the output in a client-ready format that can be moved into Notion, Google Sheets, Gmail, or Slack. 5) Remember the client context, style preferences, and accepted formats for future projects.`,heroOverlaySteps:[`Reading the brief, goals, audience, and deliverables`,`Breaking the project into research, strategy, drafting, and review tasks`,`Producing finished work with assumptions and revision points`,`Client-ready project packet assembled`],generatingSteps:[`Reading {url} to understand the project brief, constraints, and deliverables`,`Designing agents for research, strategy, drafting, analysis, and review`,`Configuring the final package, supporting notes, and client-ready formatting`,`Preparing finished freelance work with clear next steps and revision points`],featureSectionTitle:`From brief to finished project`,featureCardTitles:[`Connects to your freelance stack`,`Outputs clients can review`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Slack, Notion — Computer keeps briefs, drafts, research, and client updates organized across the tools you already use.`,`Research packets. Strategy notes. Drafted deliverables. Review checklists. Client-ready handoffs. Computer turns a brief into work you can send.`],capabilitySectionTitle:`Your freelance workbench, on autopilot`,capabilitySectionSubtitle:`Share the brief, step away, and come back to finished work packaged for client review.`,capabilityCards:[{title:`Any Project`,description:`Computer can take on research, analysis, writing, planning, and operations briefs, then shape the work into the deliverable the client asked for.`},{title:`From Brief to Done`,description:`Computer can extract requirements, close gaps, produce drafts, and package the final result with assumptions and review notes.`},{title:`Many Skills One Tool`,description:`Computer can coordinate research, strategy, writing, spreadsheet work, and client communication from one project brief.`},{title:`Connect Your Tools`,description:`Computer can organize project output in Gmail, Google Sheets, Slack, and Notion so every draft and handoff stays easy to find.`},{title:`Remember & Learn`,description:`Computer can remember client preferences, accepted formats, brand tone, and project context so future freelance work starts sharper.`},{title:`Monitor & Alert`,description:`Computer can track open questions, missing inputs, and client follow-ups, then flag the next action before the project stalls.`}]});export{t as default};
